import runSeoChecks from"./preflight-checks/seo.js";import runGeneralChecks from"./preflight-checks/general.js";import runAccessibilityChecks from"./preflight-checks/accessibility.js";export default async function decorate(e){const s=runSeoChecks(),c=runGeneralChecks(),n=runAccessibilityChecks(),i=e=>e.map(e=>`\n    <div class="seo-item ${e.icon}">\n      <h3>${e.title}</h3>\n      <p>${e.description}</p>\n    </div>\n  `).join(""),t=`\n    <div class="preflight-results">\n      <h1>CME Group Preflight Check</h1>\n      \n      <details class="preflight-check-section">\n        <summary class="preflight-check-header">SEO Checks</summary>\n        <div class="preflight-check-content">\n          ${i(s)}\n        </div>\n      </details>\n\n      <details class="preflight-check-section">\n        <summary class="preflight-check-header">General Checks</summary>\n        <div class="preflight-check-content">\n          ${i(c)}\n        </div>\n      </details>\n\n      <details class="preflight-check-section">\n        <summary class="preflight-check-header">Accessibility Checks</summary>\n        <div class="preflight-check-content">\n          ${i(n)}\n        </div>\n      </details>\n    </div>\n  `;e.innerHTML=t}